        getChartData(state) {
            var labels = state.domainState.compositeHistory.map(function(_, i) { return 'R' + (i + 1); });
            var revScores = state.domainState.revenueHistory.map(function(v) { return Math.min(100, Math.max(0, Math.round(v / 7))); });
            return { metricsChart: { labels: labels, datasets: [
                { data: state.domainState.compositeHistory },
                { data: state.domainState.ecosystemHistory },
                { data: revScores },
                { data: state.domainState.regulatoryHistory },
                { data: state.domainState.stakeholderHistory }
            ] } };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var composites = history.map(function(r) { return r.results ? r.results.composite || 0 : 0; });
            var finalComposite = composites[composites.length - 1] || 0;
            var avgComposite = Math.round(composites.reduce(function(s, v) { return s + v; }, 0) / composites.length);
            var govScores = history.map(function(r) { return r.results ? r.results.avgGovernance || 2 : 2; });
            var avgGov = govScores.reduce(function(s, v) { return s + v; }, 0) / govScores.length;

            var performance = this._t('perf_struggling');
            if (finalComposite >= 40) performance = this._t('perf_developing');
            if (finalComposite >= 60) performance = this._t('perf_strong');
            if (finalComposite >= 75) performance = this._t('perf_leader');

            var insights = [];
            if (avgGov >= 2.5) { insights.push(this._t('insight_open')); }
            else if (avgGov >= 1.8) { insights.push(this._t('insight_balanced')); }
            else { insights.push(this._t('insight_extractive')); }

            var finalRevenue = lastRecord && lastRecord.results ? lastRecord.results.revenue || 450 : 450;
            if (finalRevenue > 550) { insights.push(this._t('insight_rev_strong')); }
            else if (finalRevenue < 400) { insights.push(this._t('insight_rev_decline')); }

            var finalEH = lastRecord && lastRecord.results ? lastRecord.results.ecosystemHealth || 50 : 50;
            if (finalEH >= 75) { insights.push(this._t('insight_eh_high')); }
            else if (finalEH < 40) { insights.push(this._t('insight_eh_low')); }

            return { finalComposite: finalComposite, avgComposite: avgComposite, finalRevenue: finalRevenue, performance: performance, insights: insights };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.eventTriggered) { return this._t('hint_event_triggered'); }
            if (results.ecosystemHealth < 35) { return this._t('hint_low_ecosystem'); }
            if (results.regulatoryCompliance < 35) { return this._t('hint_regulatory_risk'); }
            if (results.avgGovernance >= 2.5) { return this._t('hint_ecosystem_leader'); }
            if (results.avgGovernance >= 1.8) { return this._t('hint_balanced'); }
            return this._t('hint_extractive');
        }

