        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var L = this._L(period);

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = L.title;
            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = L.description;

            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel && !state._keepEvent) eventPanel.style.display = 'none';

            for (var i = 0; i < 4; i++) {
                var dec = L.decisions[i];
                var labelEl = document.getElementById('decision' + (i + 1) + 'Label');
                var selectEl = document.getElementById('decision' + (i + 1) + 'Input');
                if (labelEl) labelEl.textContent = dec.label;
                if (selectEl && selectEl.options && selectEl.options.length >= 3) {
                    selectEl.options[0].text = 'A: ' + dec.optA;
                    selectEl.options[1].text = 'B: ' + dec.optB;
                    selectEl.options[2].text = 'C: ' + dec.optC;
                    selectEl.value = '2';
                }
            }
        }
